public static void main(String[] args) throws IOException {
    Reader reader = new Reader();

    final int N = reader.readInt();
    int[] Q = new int[N];
    int[] A = new int[N];
    int[] B = new int[N];

    for (int i = 0; i < N; i++) {
        Q[i] = reader.readInt();
    }

    for (int i = 0; i < N; i++) {
        A[i] = reader.readInt();
    }

    for (int i = 0; i < N; i++) {
        B[i] = reader.readInt();
    }

    reader.close();

    int total_max = 0;
    for (int n = 0; n <= Integer.MAX_VALUE; n++) {
        int m_max = Integer.MAX_VALUE;
        boolean valid = true;
        for (int i = 0; i < N; i++) {
            if (A[i] * n > Q[i]) {
                valid = false;
                break;
            }
            if (B[i] != 0) {
                int m = (Q[i] - A[i] * n) / B[i];
                if (m < m_max) {
                    m_max = m;
                }
            }
        }
        if (!valid) break;
        if (total_max < n + m_max) {
            total_max = n + m_max;
        }
    }

    System.out.println(total_max);
}
